            q: 'LLM 옵저버빌리티란 무엇인가요?',
            a: '모델 호출의 트레이스(프롬프트, 응답, 지연 시간, 토큰 사용량, 비용)를 수집하고 분석해 팀이 장애를 디버깅하고 품질 저하를 포착하며 프로덕션 지출을 모니터링할 수 있게 하는 실천입니다. 같은 입력이 다른 출력을 낼 수 있는 비결정적 동작으로 통상적인 애플리케이션 옵저버빌리티를 확장한 것으로, 여기서 장애는 오류보다 품질 저하를 뜻하는 경우가 많습니다.',
